  5158	static void*
  5159	md_push_block_bytes(MD_CTX* ctx, int n_bytes)
  5160	{
  5161	    void* ptr;
  5162	
  5163	    if(ctx->n_block_bytes + n_bytes > ctx->alloc_block_bytes) {
  5164	        void* new_block_bytes;
  5165	
